import {build} from 'esbuild';
import {copyFile, readFile, writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
process.chdir(fileURLToPath(new URL('.', import.meta.url)));
await build({absWorkingDir: process.cwd(), entryPoints: ['core.js'], outfile: 'core.bundle.js', bundle: true, platform: 'browser', format: 'iife', legalComments: 'eof', plugins: [{
  name: 'realm-private-core-js-store',
  setup(builder) {
    // One bundled core-js instance owns this store. Preserve its shared-module
    // lifetime without registering dependency metadata on the page's global.
    builder.onLoad({filter: /[/\\]core-js-pure[/\\]internals[/\\]shared-store\.js$/}, () => ({contents: 'module.exports = {};', loader: 'js'}));
  },
}]});
const storage = await build({absWorkingDir: process.cwd(), entryPoints:['storage.js'], bundle:true, platform:'browser', format:'iife', globalName:'__BrimpStorage', write:false, legalComments:'eof'});
await writeFile('../plugins/storage.js', '// Generated by js/vendor/build.mjs. Edit vendor/storage*.js.\n(context) => {\n' + storage.outputFiles[0].text + '\nreturn __BrimpStorage.install(context);\n}\n');
const licenses = {'core-js-pure': 'LICENSE', xpath: 'LICENSE', 'fake-indexeddb':'LICENSE', 'web-streams-polyfill':'LICENSE'};
for (const [name, file] of Object.entries(licenses)) await copyFile(`node_modules/${name}/${file}`, `${name}.LICENSE`);
const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');
await writeFile('manifest.json', JSON.stringify({packages: JSON.parse(await readFile('package.json')).dependencies, lockSha256: sha256(await readFile('package-lock.json')), bundleSha256: sha256(await readFile('core.bundle.js')), storageSha256: sha256(await readFile('../plugins/storage.js'))}, null, 2) + '\n');
